/**
 * Localized labels for product ATTRIBUTE NAMES (the row labels in Product
 * Details / Specifications). WordPress attribute taxonomies: color, flavor,
 * manufacturer, size, style, variant — plus the material taxonomy. Keyed by the
 * normalized attribute name (see normalizeAttributeKey). Unmapped names fall
 * back to the formatted English label.
 */
const ATTRIBUTE_LABELS: Record<string, Record<string, string>> = {
  de: { color: 'Farbe', material: 'Material', flavor: 'Geschmack', manufacturer: 'Hersteller', size: 'Größe', style: 'Stil', variant: 'Variante' },
  fr: { color: 'Couleur', material: 'Matériau', flavor: 'Parfum', manufacturer: 'Fabricant', size: 'Taille', style: 'Style', variant: 'Variante' },
  es: { color: 'Color', material: 'Material', flavor: 'Sabor', manufacturer: 'Fabricante', size: 'Talla', style: 'Estilo', variant: 'Variante' },
  ja: { color: 'カラー', material: '素材', flavor: 'フレーバー', manufacturer: 'メーカー', size: 'サイズ', style: 'スタイル', variant: 'バリエーション' },
  zh: { color: '颜色', material: '材质', flavor: '口味', manufacturer: '制造商', size: '尺寸', style: '款式', variant: '款式变化' },
  'zh-hant': { color: '顏色', material: '材質', flavor: '口味', manufacturer: '製造商', size: '尺寸', style: '款式', variant: '款式變化' },
};

/** Decode the handful of HTML entities WordPress leaves in stored term names. */
function decodeEntities(s: string): string {
  return s
    .replace(/&amp;/gi, '&')
    .replace(/&#0*38;/g, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#0*39;/g, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&nbsp;/gi, ' ');
}

function localize(
  map: Record<string, Record<string, string>>,
  slug: string | undefined,
  fallbackName: string,
  locale: string,
): string {
  const hit = slug ? map[locale]?.[slug] : undefined;
  return hit ?? decodeEntities(fallbackName ?? '');
}

/** Localize a color name by taxonomy slug; falls back to the English name. */
export function localizeColorName(slug: string | undefined, fallbackName: string, locale: string): string {
  return localize(COLOR_NAMES, slug, fallbackName, locale);
}

/** Localize a material name by taxonomy slug; falls back to the English name. */
export function localizeMaterialName(slug: string | undefined, fallbackName: string, locale: string): string {
  return localize(MATERIAL_NAMES, slug, fallbackName, locale);
}

/** Client hook: (slug, name) => localized color name for the active locale. */
export function useLocalizedColorName(): (slug: string | undefined, name: string) => string {
  const locale = useLocale();
  return (slug, name) => localizeColorName(slug, name, locale);
}

/** Client hook: (slug, name) => localized material name for the active locale. */
export function useLocalizedMaterialName(): (slug: string | undefined, name: string) => string {
  const locale = useLocale();
  return (slug, name) => localizeMaterialName(slug, name, locale);
}

/** Normalize an attribute name to an ATTRIBUTE_LABELS key: strip pa_ prefix, lowercase, drop separators. */
function normalizeAttributeKey(name: string): string {
  return name.toLowerCase().replace(/^pa[\s_-]+/, '').replace(/[\s_-]+/g, '');
}

/**
 * Localize a product attribute's NAME (e.g. "Color", "pa_size") for display.
 * Falls back to the supplied (already-formatted English) label when unmapped.
 */
export function localizeAttributeName(name: string, fallbackLabel: string, locale: string): string {
  return ATTRIBUTE_LABELS[locale]?.[normalizeAttributeKey(name)] ?? fallbackLabel;
}

/** Client hook: (name, fallbackLabel) => localized attribute label for the active locale. */
export function useLocalizedAttributeName(): (name: string, fallbackLabel: string) => string {
  const locale = useLocale();
  return (name, fallbackLabel) => localizeAttributeName(name, fallbackLabel, locale);
}

/**
 * Client hook for localizing a stored variation attribute (cart / checkout line
 * items), where attributes are kept as { name: value } in English. Localizes
 * the attribute NAME via the label dictionary and the VALUE via the color /
 * material dictionaries (other attribute values pass through unchanged).
 */
export function useLocalizedVariationAttribute(): (name: string, value: string) => { name: string; value: string } {
  const locale = useLocale();
  return (name, value) => {
    const kind = name.toLowerCase().replace(/^pa[\s_-]+/, '').replace(/[\s_-]+/g, '');
    const slug = value.toLowerCase().replace(/\s+/g, '-');
    let localizedValue = value;
    if (kind === 'color') localizedValue = localizeColorName(slug, value, locale);
    else if (kind === 'material') localizedValue = localizeMaterialName(slug, value, locale);
    return { name: localizeAttributeName(name, name, locale), value: localizedValue };
  };
}
